const {presets,calc}=UNARAPurchase;
const $=id=>document.getElementById(id),usd=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v),percent=v=>v==null?'—':(v*100).toFixed(1)+'%';
let asset='home',s={...presets.home};
const ranges={home:{price:[300000,800000,10000],rent:[1500,6000,100],insurance:[1000,8000,100],hoa:[0,6000,100]},flex:{price:[1000000,5000000,50000],rent:[7000,50000,500],insurance:[4000,50000,500],hoa:[0,30000,500]}};
function control(key,label,min,max,step,format='money'){
  const fmt=v=>format==='money'?usd(v):format==='months'?`${v} meses`:`${v}%`;
  return `<div class="control"><label for="p-${key}">${label}<output id="pout-${key}">${fmt(s[key])}</output></label><input id="p-${key}" data-purchase="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${s[key]}"><div class="endpoints"><span>${fmt(min)}</span><span>${fmt(max)}</span></div></div>`;
}
function line(label,value,emphasis=false){return `<div class="purchase-line${emphasis?' emphasis':''}"><span>${label}</span><strong>${usd(value)}</strong></div>`}
function configure(){const r=ranges[asset];$('priceControl').innerHTML=control('price','Precio de compra · referencia',...r.price);$('rentControl').innerHTML=control('rent','Renta potencial mensual',...r.rent);$('closingControl').innerHTML=control('closing','Gastos de compra · supuesto',0,5,.25,'percent');$('creditControl').innerHTML=control('credit','Crédito al cierre',0,70,5,'percent');$('rateControl').innerHTML=control('rate','Tasa anual del crédito',7,12,.25,'percent');$('vacancyControl').innerHTML=control('vacancy','Vacancia estimada',0,25,1,'percent');$('taxControl').innerHTML=control('tax','Property tax anual',0,4,.1,'percent');$('insuranceControl').innerHTML=control('insurance','Seguro anual del propietario',...r.insurance);$('managementControl').innerHTML=control('management','Administración · % de renta cobrada',0,15,1,'percent');$('maintenanceControl').innerHTML=control('maintenance','Mantenimiento · % de renta cobrada',0,15,1,'percent');$('reserveControl').innerHTML=control('reserve','Reserva · % de renta cobrada',0,10,1,'percent');$('hoaControl').innerHTML=control('hoa','HOA anual',...r.hoa);$('growthControl').innerHTML=control('growth','Cambio anual del valor · supuesto',-3,5,.25,'percent');$('rentGrowthControl').innerHTML=control('rentGrowth','Cambio anual de la renta · supuesto',-2,5,.25,'percent');$('sellingControl').innerHTML=control('selling','Costos de venta hipotética',0,8,.5,'percent');render()}
function render(){
  const r=calc(s),f=r.first;
  document.querySelectorAll('[data-asset]').forEach(b=>{const on=b.dataset.asset===asset;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on)});
  $('purchaseImage').src=asset==='home'?'home.jpg':'flex-modular.png';$('purchaseImage').alt=asset==='home'?'Fotografía residencial de referencia':'Render ilustrativo de unidades comerciales e industriales flex';
  $('capitalFigures').innerHTML=`<div><span>PRECIO DE COMPRA</span><strong>${usd(r.price)}</strong><small>Referencia ilustrativa; se confirma al seleccionar un inmueble</small></div><div><span>CRÉDITO AL CIERRE</span><strong>${usd(r.loan)}</strong></div><div><span>CAPITAL TOTAL APORTADO</span><strong>${usd(r.equity)}</strong><small>Incluye ${usd(r.closing)} de gastos de compra</small></div>`;
  $('capitalTimeline').innerHTML=`<div><span>01 / CIERRE</span><strong>${usd(r.equity)}</strong><small>Tu aportación y gastos · mes 0<br>Banco: ${usd(r.loan)}</small></div><div><span>02 / OPERACIÓN</span><strong>Mes 1</strong><small>Comienza la renta proyectada, sujeto a ocupación</small></div>`;
  $('operatingRows').innerHTML=line('Renta potencial mensual',f.rent)+line('Vacancia estimada',f.effective-f.rent)+line('Renta efectivamente cobrada',f.effective,true)+line('Property tax',-f.tax)+line('Seguro del inmueble · propietario',-f.insurance)+line('HOA',-f.hoa)+line('Administración',-f.mgmt)+line('Mantenimiento',-f.maint)+line('Ingreso operativo neto / NOI',f.noi,true)+line('Reserva para reparaciones mayores',-f.reserve)+line('Pago hipotecario',-f.debt)+line('Flujo mensual después de deuda',f.cf,true);
  $('cashflowFigure').innerHTML=`<span>FLUJO MENSUAL · PRIMER AÑO OPERATIVO</span><strong class="${f.cf<0?'negative':''}">${usd(f.cf)}</strong><p>${f.cf<0?`La renta no cubre ${usd(-f.cf)} al mes bajo estos supuestos.`:'Después de gastos, reservas y crédito.'}</p>`;
  $('returnFigures').innerHTML=`<div><span>RENDIMIENTO DEL INMUEBLE</span><strong>${percent(r.capRate)}</strong><small>NOI anual / precio de compra · sin deuda</small></div><div><span>FLUJO SOBRE TU CAPITAL</span><strong class="${r.cashOnCash<0?'negative':''}">${percent(r.cashOnCash)}</strong><small>Flujo del primer año / capital aportado</small></div><div><span>RESULTADO TOTAL · 5 AÑOS</span><strong class="${r.totalROI<0?'negative':''}">${percent(r.totalROI)}</strong><small>Rentas + venta hipotética − capital aportado</small></div><div><span>TIR ANUALIZADA · 5 AÑOS</span><strong class="${r.irr<0?'negative':''}">${percent(r.irr)}</strong><small>Incluye aportación, flujos y venta hipotética</small></div>`;
  const maxCash=Math.max(...r.annual.map(x=>Math.abs(x.cf)),1),minVal=Math.min(s.price,...r.annual.map(x=>x.value)),maxVal=Math.max(s.price,...r.annual.map(x=>x.value)),span=maxVal-minVal||1;
  $('yearChart').innerHTML=r.annual.map(y=>`<div class="purchase-year"><span>0${y.year}</span><div class="year-flow"><strong class="${y.cf<0?'negative':''}">${usd(y.cf)}</strong><i class="${y.cf<0?'negative':''}" style="width:${Math.max(2,Math.abs(y.cf)/maxCash*100)}%"></i></div><div class="year-value"><strong>${usd(y.value)}</strong><i style="width:${20+(y.value-minVal)/span*80}%"></i></div></div>`).join('');
  $('purchaseTable').innerHTML='<thead><tr><th>Concepto</th>'+r.annual.map(y=>`<th>Año ${y.year}</th>`).join('')+'</tr></thead><tbody>'+[['Renta cobrada','rent'],['Ingreso operativo neto','noi'],['Flujo después de deuda','cf'],['Flujo acumulado','cumulative'],['Valor estimado','value'],['Saldo hipotecario','balance'],['Equity en la propiedad','equity']].map(([label,key])=>`<tr><th>${label}</th>${r.annual.map(y=>`<td>${usd(y[key])}</td>`).join('')}</tr>`).join('')+'</tbody>';
  $('exitRows').innerHTML=line('Valor estimado al final del año 5',r.last.value)+line('Costos hipotéticos de venta',-r.selling)+line('Saldo hipotecario a liquidar',-r.last.balance)+line('Efectivo neto hipotético de venta',r.exitNet,true)+line('Flujo de rentas acumulado',r.last.cumulative)+line('Capital aportado',-r.equity)+line('Resultado total antes de impuestos',r.profit,true);
}
document.addEventListener('input',e=>{const key=e.target.dataset.purchase;if(!key)return;s[key]=Number(e.target.value);render();const out=$('pout-'+key);if(out)out.textContent=['closing','credit','rate','vacancy','tax','management','maintenance','reserve','growth','rentGrowth','selling'].includes(key)?`${s[key]}%`:usd(s[key])});
document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>{asset=b.dataset.asset;s={...presets[asset]};configure()});
configure();
